class Solution {
public:
    int numOfSubarrays(vector<int>& arr, int k, int threshold) {
        long long target = (long long)k * threshold;
        long long sum = 0;
        int count = 0;
        int n = (int)arr.size();
        for (int i = 0; i < n; i++) {
            sum += arr[i];
            if (i >= k) sum -= arr[i - k];
            if (i >= k - 1 && sum >= target) count++;
        }
        return count;
    }
};
